-- 12.1 cleanup Phase A: child rows whose parent is missing in tc_world.
-- Does not delete creature/quest templates of old expansions.
SET NAMES utf8mb4;

DELETE qp FROM `quest_poi` qp LEFT JOIN `quest_template` qt ON qt.`ID` = qp.`QuestID` WHERE qt.`ID` IS NULL;
DELETE qpp FROM `quest_poi_points` qpp LEFT JOIN `quest_template` qt ON qt.`ID` = qpp.`QuestID` WHERE qt.`ID` IS NULL;
DELETE qd FROM `quest_details` qd LEFT JOIN `quest_template` qt ON qt.`ID` = qd.`ID` WHERE qt.`ID` IS NULL;
DELETE qri FROM `quest_request_items` qri LEFT JOIN `quest_template` qt ON qt.`ID` = qri.`ID` WHERE qt.`ID` IS NULL;
DELETE qor FROM `quest_offer_reward` qor LEFT JOIN `quest_template` qt ON qt.`ID` = qor.`ID` WHERE qt.`ID` IS NULL;
DELETE qms FROM `quest_mail_sender` qms LEFT JOIN `quest_template` qt ON qt.`ID` = qms.`QuestId` WHERE qt.`ID` IS NULL;

DELETE ca FROM `creature_addon` ca LEFT JOIN `creature` c ON c.`guid` = ca.`guid` WHERE c.`guid` IS NULL;
DELETE ga FROM `gameobject_addon` ga LEFT JOIN `gameobject` g ON g.`guid` = ga.`guid` WHERE g.`guid` IS NULL;
DELETE cta FROM `creature_template_addon` cta LEFT JOIN `creature_template` t ON t.`entry` = cta.`entry` WHERE t.`entry` IS NULL;
DELETE ctd FROM `creature_template_difficulty` ctd LEFT JOIN `creature_template` t ON t.`entry` = ctd.`Entry` WHERE t.`entry` IS NULL;
DELETE ctm FROM `creature_template_model` ctm LEFT JOIN `creature_template` t ON t.`entry` = ctm.`CreatureID` WHERE t.`entry` IS NULL;
DELETE cts FROM `creature_template_spell` cts LEFT JOIN `creature_template` t ON t.`entry` = cts.`CreatureID` WHERE t.`entry` IS NULL;
DELETE ctg FROM `creature_template_gossip` ctg LEFT JOIN `creature_template` t ON t.`entry` = ctg.`CreatureID` WHERE t.`entry` IS NULL;
DELETE ce FROM `creature_equip_template` ce LEFT JOIN `creature_template` t ON t.`entry` = ce.`CreatureID` WHERE t.`entry` IS NULL;

DELETE pt FROM `pool_template` pt LEFT JOIN `pool_members` pm ON pm.`poolSpawnId` = pt.`entry` WHERE pm.`poolSpawnId` IS NULL;

DELETE gmo FROM `gossip_menu_option` gmo LEFT JOIN `gossip_menu` gm ON gm.`MenuID` = gmo.`MenuID` WHERE gm.`MenuID` IS NULL;
DELETE ctg FROM `creature_template_gossip` ctg LEFT JOIN `gossip_menu` gm ON gm.`MenuID` = ctg.`MenuID` WHERE gm.`MenuID` IS NULL;
-- conditions SourceType 14/15 = gossip menu / option
DELETE c FROM `conditions` c LEFT JOIN `gossip_menu` gm ON gm.`MenuID` = c.`SourceGroup` WHERE c.`SourceTypeOrReferenceId` IN (14,15) AND gm.`MenuID` IS NULL;

DELETE qo FROM `quest_objectives` qo LEFT JOIN `quest_template` qt ON qt.`ID` = qo.`QuestID` WHERE qt.`ID` IS NULL;
DELETE qo FROM `quest_objectives` qo LEFT JOIN `creature_template` t ON t.`entry` = qo.`ObjectID` WHERE qo.`Type` IN (0,3) AND qo.`ObjectID` > 0 AND t.`entry` IS NULL;
DELETE qo FROM `quest_objectives` qo LEFT JOIN `gameobject_template` t ON t.`entry` = qo.`ObjectID` WHERE qo.`Type` = 2 AND qo.`ObjectID` > 0 AND t.`entry` IS NULL;

